func statusTone(s string) string {
	switch s {
	case "active":
		return "success"
	case "expired":
		return "error"
	}
	return "neutral"
}

func onlineLabel(on bool) string {
	if on {
		return "Online"
	}
	return "Offline"
}

func onlineTitle(on bool) string {
	if on {
		return "online"
	}
	return "offline"
}

